# -*- coding: utf-8 -*-
# Финальные счета, платёж 3 (45% доли, сдача Системы, 450 000 ₸): BUB-С-2026-06 (Тимур) и BUB-С-2026-07 (Талгат).
# Строится из счетов платежа 2 app/schet-bubnovsky-{slug}-2.html (их собирает schet2.py).
import os,re
ROOT=os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),'..','..','..','..'))
for slug,p1,p2,new,num in (('timur','BUB-С-2026-01','BUB-С-2026-04','BUB-С-2026-06','BUB-2026-01'),('talgat','BUB-С-2026-02','BUB-С-2026-05','BUB-С-2026-07','BUB-2026-02')):
    s=open(ROOT+f'/app/schet-bubnovsky-{slug}-2.html',encoding='utf-8').read()
    R=[('платёж 2 из 3','платёж 3 из 3 · финальный'),('<div class="badge">ЛФК · Ядро</div>','<div class="badge">ЛФК · Сдача</div>'),
     ('от 4 ноября 2026 г.<br>Действителен до 11.11.2026','от 13 ноября 2026 г.<br>Действителен до 20.11.2026'),
     ('ПЛАТЁЖ 2 · 45% ДОЛИ · УТВЕРЖДЕНИЕ ЯДРА СИСТЕМЫ','ПЛАТЁЖ 3 · 45% ДОЛИ · СДАЧА СИСТЕМЫ · ФИНАЛЬНЫЙ'),
     (f'Второй платёж по <b>Договору № {num} от 27.10.2026</b> (п. 2.4, п. 3.2) — после утверждения ядра Системы',f'Финальный платёж по <b>Договору № {num} от 27.10.2026</b> (п. 2.4) — сдача Системы'),
     ('Предоплата 10% (100 000 ₸) получена. Оплата — в течение 5 рабочих дней с даты акта утверждения ядра.','Платежи 1 (100 000 ₸) и 2 (450 000 ₸) получены. Оплата — в течение 5 рабочих дней с даты акта сдачи Системы.'),
     ('НАЗНАЧЕНИЕ ПЛАТЕЖА · 45% ДОЛИ (50%) · ЯДРО СИСТЕМЫ','НАЗНАЧЕНИЕ ПЛАТЕЖА · 45% ДОЛИ (50%) · СДАЧА СИСТЕМЫ'),
     (f'<b>Платёж 2 — 45% доли Заказчика за разработку программного обеспечения по Договору № {num} от 27.10.2026, утверждение ядра Системы (п. 3.2).</b>',f'<b>Платёж 3 (финальный) — 45% доли Заказчика за разработку программного обеспечения по Договору № {num} от 27.10.2026, сдача Системы.</b>'),
     (f'<div class="step"><span>Платёж 1 · 10% — предоплата, старт работ · оплачено ({p1})</span><span>100 000 ₸</span></div>\n    <div class="step cur"><span>Платёж 2 · 45% — утверждение ядра Системы<span class="tg">← настоящий счёт</span></span><span>450 000 ₸</span></div>\n    <div class="step"><span>Платёж 3 · 45% — сдача Системы</span><span>450 000 ₸</span></div>',
      f'<div class="step"><span>Платёж 1 · 10% — предоплата, старт работ · оплачено ({p1})</span><span>100 000 ₸</span></div>\n    <div class="step"><span>Платёж 2 · 45% — утверждение ядра Системы · оплачено ({p2})</span><span>450 000 ₸</span></div>\n    <div class="step cur"><span>Платёж 3 · 45% — сдача Системы<span class="tg">← настоящий счёт</span></span><span>450 000 ₸</span></div>'),
     ('К ОПЛАТЕ — 45% ДОЛИ<span>2-й из 3 платежей по доле · утверждение ядра</span>','К ОПЛАТЕ — 45% ДОЛИ<span>3-й, финальный платёж по доле · сдача Системы</span>'),
     (f'Договор № {num} от 27.10.2026, п. 2.4, платёж 2',f'Договор № {num} от 27.10.2026, п. 2.4, платёж 3'),
     (f'Оплата по счёту {p2} от 04.11.2026, платёж 2 (45%, утверждение ядра) по договору',f'Оплата по счёту {new} от 13.11.2026, платёж 3 (45%, сдача Системы, финальный) по договору'),
     ('Дата выставления: 04.11.2026 · Срок оплаты: до 11.11.2026','Дата выставления: 13.11.2026 · Срок оплаты: до 20.11.2026'),
     ('· платёж 2 · 45%</span>','· платёж 3 · 45% · финальный</span>')]
    for a,b in R:
        assert a in s,(slug,a[:70]);s=s.replace(a,b)
    s=s.replace(p2,new).replace(f'оплачено ({new})',f'оплачено ({p2})')
    s=re.sub(r'<title>.*?</title>',lambda m:m.group(0).replace('платёж 2 · 45%','платёж 3 · 45% · финальный'),s,1)
    open(ROOT+f'/app/schet-bubnovsky-{slug}-3.html','w',encoding='utf-8').write(s)
    print('ok',slug)
